"""Build the static review gallery from its saved concept manifest. No game integration."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent
data = json.loads((ROOT / 'generation-prompts.json').read_text())
details = {
    'payment-a': ('Card origin stays clear', 'Each card has separate choices for bowing and using its Reaction. Destruction and removal costs stay explicit.', 'Best foundation; the source list needs scrolling for large economies.'),
    'payment-b': ('Physical payment tray', 'Full card faces sit beside a payment receipt, with the selected method attached to each card.', 'Readable cards, but the extra tray takes more space from the table.'),
    'payment-c': ('Cost and consequence receipt', 'The receipt separates contributed Gold, cost reduction and the adjusted cost. Selected consequences remain beside confirmation.', 'Use this receipt with A’s source list and the existing engine suggestions.'),
    'choice-a': ('One focused sidebar', 'The source card, cost options, candidate cards and consequence appear together.', 'Compact and familiar, but small candidate faces are harder to compare.'),
    'choice-b': ('Room to compare cards', 'A temporary tray provides readable candidates while the source remains separately visible.', 'Best for choosing between several cards; keep the normal hand fully visible.'),
    'choice-c': ('Choose directly in the hand', 'Eligible cards are marked in their existing positions. The sidebar repeats the selected card and destination.', 'Good for small choices; eligibility and confirmation must remain unmistakable.'),
}
for item in data['concepts']:
    if item['id'] == 'payment-c':
        item['title'] = 'C — Clear payment receipt'
    item['image'] = 'images/' + item['id'] + '.png'
    item['subtitle'], item['description'], item['tradeoff'] = details[item['id']]
payload = json.dumps(data['concepts'], ensure_ascii=False).replace('</', '<\\/')
html = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>L5R · Gameplay Controls Concepts</title>
<style>
:root{color-scheme:dark;--gold:#d3b778;--muted:#aab1b5;--panel:#141b22}*{box-sizing:border-box}body{margin:0;background:#0c1218;color:#ece5d7;font:17px/1.55 Georgia,serif}main{max-width:1700px;margin:auto;padding:28px 32px 50px}header{display:flex;justify-content:space-between;gap:24px;align-items:start;border-bottom:1px solid #665534;padding-bottom:22px}h1{font-size:31px;font-weight:400;margin:0}h2{font-size:24px;font-weight:400;margin:0 0 10px}p{margin:8px 0}.eyebrow{font:12px/1.5 system-ui;letter-spacing:.13em;text-transform:uppercase;color:var(--gold)}.status{font:14px system-ui;color:#c7b997;text-align:right;max-width:310px}.status a,a{color:#b9d8e7}nav,.choices{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}button,.open-image{border:1px solid #6c6044;background:#161e26;color:#e8dfcd;padding:11px 18px;font:16px Georgia;cursor:pointer;border-radius:3px}button:hover,button:focus-visible,.open-image:hover{border-color:var(--gold);outline:2px solid #a79d69;outline-offset:3px}button[aria-pressed=true]{background:#363020;border-color:var(--gold);color:#fff0bc}.recommendation{padding:17px 22px;border-left:3px solid var(--gold);background:#1a2128;margin:16px 0}.recommendation strong{color:#f1d796}figure{margin:0;border:1px solid #3b454d;background:#070b0f}figure img{display:block;width:100%;height:auto;cursor:zoom-in}figcaption{padding:15px 20px;display:flex;justify-content:space-between;gap:20px;align-items:center}.caption{max-width:1000px}.caption b{color:var(--gold)}.tradeoff{color:var(--muted);font-size:15px}.open-image{white-space:nowrap;text-decoration:none}.thumbs{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}.thumbs button{padding:0;text-align:left;overflow:hidden}.thumbs img{width:100%;display:block}.thumbs span{display:block;padding:10px 14px}.footnote{font:14px/1.6 system-ui;color:var(--muted);margin:20px 0}.roadmap{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:35px}.roadmap article{border-top:1px solid #625236;padding-top:14px}.roadmap p{color:var(--muted);font-size:16px}.roadmap strong{color:var(--gold)}dialog{border:1px solid #7e6940;background:#080d11;color:#eee;width:96vw;max-width:none;max-height:96vh;padding:12px}dialog::backdrop{background:#000c}dialog img{display:block;width:100%;height:auto}dialog button{position:sticky;top:0;float:right}.links{display:flex;gap:20px;margin-top:30px;font-size:15px}@media(max-width:750px){main{padding:20px 12px}header{display:block}.status{text-align:left;margin-top:12px}h1{font-size:26px}figcaption{display:block}.open-image{display:inline-block;margin-top:12px}.roadmap{grid-template-columns:1fr}.thumbs{gap:6px}.thumbs span{font-size:13px;padding:7px}}
</style>
<main><header><div><div class="eyebrow">Legend of the Five Rings · UI/QoL review</div><h1>Gameplay choices &amp; payment controls</h1><p>Three payment directions and three choice directions, based on the approved game interface.</p></div><div class="status">Static imagegen concepts<br>These changes are awaiting visual selection.<br><a href="https://github.com/alfredoh7/l5r-emperor/pull/570">Draft review #570</a></div></header>
<nav aria-label="Concept family"><button data-family="payment" aria-pressed="true">1 · Payment controls</button><button data-family="choice" aria-pressed="false">2 · Choice &amp; cost tray</button></nav>
<div class="recommendation" id="recommendation"></div><div class="choices" id="choices" aria-label="Concept variation"></div>
<figure><img id="hero" alt=""><figcaption><div class="caption"><b id="title"></b><p id="description"></p><p class="tradeoff" id="tradeoff"></p></div><a class="open-image" id="full" href="#" target="_blank" rel="noopener">Open full image</a></figcaption></figure>
<div class="thumbs" id="thumbs" aria-label="All variations"></div>
<p class="footnote">Concept artwork explores layout, selection and consequences. Payment amounts are illustrative. Generated card imagery and lettering are not authoritative scans or rules; implementation uses the actual period artwork, engine quotes and offered commands. This gallery does not submit game actions or record approval.</p>
<section class="roadmap" aria-label="Implementation sequence"><article><strong>Batch 1 · Payments</strong><p>Source methods, discounts, accurate totals and clear confirmation. Test both bowing and a Reaction on one card, destructive sources, variable and zero payments.</p></article><article><strong>Batch 2 · Decisions</strong><p>Event, Honor and entry-cost choices through the existing approved interfaces. Show the source, deciding player, selectable cards and destination.</p></article><article><strong>Batch 3 · Optional opportunities</strong><p>Extra actions, reactions, Favor abilities and destination/target choices. Keep declining an opportunity distinct from passing.</p></article></section>
<p class="footnote">Each runtime batch will have a direct native Mac launcher and a self-contained Windows review for Mendon, plus real engine checks. Current delivery: concepts only. Nothing from this branch has been merged.</p>
<div class="links"><a href="PLAN.md">Detailed scope &amp; integration plan</a><a href="generation-prompts.json">Saved imagegen prompts &amp; provenance</a></div>
</main><dialog id="zoom"><button id="closeZoom">Close image · Esc</button><img id="zoomImage" alt=""></dialog>
<script>
const concepts=__DATA__;
const recommendations={payment:'<strong>Recommendation: A’s source-card layout + C’s clearer receipt.</strong><p>Show each card’s separate payment methods, then keep the selected total and any destruction/removal costs immediately above confirmation. Gold and cost reduction remain separate. Retain the engine’s suggested payments.</p>',choice:'<strong>Recommendation: B’s readable candidate tray + A’s compact source context + C’s quiet selection cue.</strong><p>Use a temporary tray for comparing several cards, keep the source separate, and repeat the selected card’s destination beside confirmation. Simple completed choices can advance directly.</p>'};
let family='payment',selected='payment-a';
function show(id){const c=concepts.find(c=>c.id===id);if(!c)return;family=c.family;selected=c.id;document.querySelectorAll('[data-family]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.family===family));document.getElementById('recommendation').innerHTML=recommendations[family];const hero=document.getElementById('hero');hero.src=c.image;hero.alt=c.title+' — '+c.description;document.getElementById('title').textContent=c.title+' · '+c.subtitle;document.getElementById('description').textContent=c.description;document.getElementById('tradeoff').textContent=c.tradeoff;document.getElementById('full').href=c.image;for(const area of ['choices','thumbs']){const el=document.getElementById(area);el.replaceChildren();concepts.filter(x=>x.family===family).forEach(x=>{const b=document.createElement('button');b.setAttribute('aria-pressed',x.id===selected);b.onclick=()=>{location.hash=x.id};if(area==='thumbs'){const img=document.createElement('img');img.src=x.image;img.alt=x.title;img.loading='lazy';b.append(img);const label=document.createElement('span');label.textContent=x.title;b.append(label);}else b.textContent=x.title;b.dataset.concept=x.id;el.append(b);});}document.title='L5R · '+c.title;}
document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.family+'-a'});
function route(){show(location.hash.slice(1)||'payment-a')}addEventListener('hashchange',route);route();
const dialog=document.getElementById('zoom');document.getElementById('hero').onclick=()=>{const c=concepts.find(c=>c.id===selected);const image=document.getElementById('zoomImage');image.src=c.image;image.alt=c.title;dialog.showModal();};document.getElementById('closeZoom').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
</script></html>'''
(ROOT / 'index.html').write_text(html.replace('__DATA__', payload))
print('Built index.html with six concepts and two recommendations.')
